SELECT json_build_object('id',t.id,'state',t.state,'verification',t.verification,'accepted_at',t.accepted_at,'first_response_at',t.first_response_at,'active_attempt_id',t.active_attempt_id,'version',t.version,'history',(SELECT json_agg(json_build_object('action',action,'version',ticket_version) ORDER BY ticket_version) FROM intake.ticket_versions WHERE ticket_id=t.id),'attempts',(SELECT json_agg(json_build_object('id',id,'outcome',outcome,'resolved_at',resolved_at,'confirmation_due_at',confirmation_due_at,'confirmation_seconds',extract(epoch from confirmation_due_at-resolved_at)) ORDER BY resolved_at) FROM intake.resolution_attempts WHERE ticket_id=t.id),'decisions',(SELECT json_agg(decision ORDER BY created_at) FROM intake.confirmation_events WHERE ticket_id=t.id),'escalation_marks',(SELECT count(*) FROM intake.escalation_marks WHERE ticket_id=t.id)) FROM intake.tickets t WHERE id='4c41da9e-f66e-48db-b30b-6ca31f1752c4';
